const books = [{ id: 1, title: 'Dune' }];
const findById = (id) => books.find((b) => b.id === id);
const asText = (b) => b.title.toUpperCase();
const show = (id, view) => {
  const book = findById(id);
  return book ? view(book) : 'missing';
};
console.log(show(1, asText), show(2, asText));
